package builtin

import (
	"fmt"
	"io"
	"strings"

	"github.com/donaldgifford/repo-guardian/internal/control"
)

// WriteReference renders every built-in type's rule kinds and parameters
// as markdown: the source of docs/usage/controls-reference.md, which
// `make lint-controls-docs` keeps current. Output depends only on the
// types, so it is byte-stable across runs.
func WriteReference(w io.Writer) error {
	var b strings.Builder

	b.WriteString(`# Control-type reference

<!-- Generated by ` + "`repo-guardian controls docs`" + `; do not edit. Run ` + "`make controls-docs`" + `. -->

Every control type repo-guardian ships, with the rule kinds a catalogue
definition may declare and each kind's parameters. A remediable kind may
declare ` + "`remediate = true`" + `.

`)

	for _, typ := range Types() {
		writeType(&b, typ)
	}

	if _, err := io.WriteString(w, b.String()); err != nil {
		return fmt.Errorf("write controls reference: %w", err)
	}

	return nil
}

func writeType(b *strings.Builder, typ control.Type) {
	fmt.Fprintf(b, "## `%s`\n\n", typ.Name())
	fmt.Fprintf(b, "- Semantics: %d\n", typ.Semantics())

	if _, api := typ.(control.APIType); api {
		applies := []string{control.ApplyRecommend, control.ApplyDirect}
		if _, ok := typ.(control.WorkflowApply); ok {
			applies = append(applies, control.ApplyWorkflow)
		}

		fmt.Fprintf(b, "- Remediates by: API (`apply` = %s)\n\n", quoteAll(applies))
	} else {
		b.WriteString("- Remediates by: pull request (takes no `apply`)\n\n")
	}

	b.WriteString("| Rule kind | Remediable | Parameters |\n|---|---|---|\n")

	for _, k := range typ.RuleKinds() {
		fmt.Fprintf(b, "| `%s` | %s | %s |\n", k.Kind, yesNo(k.Remediable), params(k.Params))
	}

	b.WriteString("\n")
}

func params(ps []control.ParamSpec) string {
	if len(ps) == 0 {
		return "—"
	}

	out := make([]string, 0, len(ps))

	for _, p := range ps {
		s := fmt.Sprintf("`%s` (%s", p.Name, p.Type)
		if p.Required {
			s += ", required"
		}

		out = append(out, s+")")
	}

	return strings.Join(out, "<br>")
}

func quoteAll(ss []string) string {
	out := make([]string, 0, len(ss))
	for _, s := range ss {
		out = append(out, "`"+s+"`")
	}

	return strings.Join(out, ", ")
}

func yesNo(ok bool) string {
	if ok {
		return "yes"
	}

	return "no"
}
